import io
R = 'D:/PoB_work/wt_m1069/'
W = 'D:/PoB_work/m1069_work/'
def rd(p): return open(R + p, 'rb').read()
def wr(p, b): open(R + p, 'wb').write(b)
def one(b, old, new):
    old = old.encode('utf-8'); new = new.encode('utf-8')
    assert b.count(old) == 1, (old[:80].decode('utf-8', 'replace'), b.count(old))
    return b.replace(old, new)

